class Batch:
    def __init__(self, item_id, batch_id, size=None):
        self.item_id, self.batch_id = self._norm_ids(item_id, batch_id)
        self.size = None if size is None else _size(size)

    @staticmethod
    def _norm_ids(item_id, batch_id):
        item, batch = int(item_id), int(batch_id)
        if not (0 <= item <= 9999 and 0 <= batch <= 99):
            raise ValueError('item or batch ID out of range')
        return f'{item:04d}', f'{batch:02d}'

    @property
    def item_name(self):
        prefix = f'{self.size}_' if self.size else ''
        return f'{prefix}covers_{self.item_id}'

    @property
    def zip_name(self):
        return f'{self.item_name}_{self.batch_id}.zip'

    @classmethod
    def get_relpath(cls, item_id, batch_id, size='', ext='zip'):
        batch = cls(item_id, batch_id, size)
        return os.path.join('items', batch.item_name, f'{batch.item_name}_{batch.batch_id}.{ext.lstrip(\".\")}')

    @classmethod
    def get_abspath(cls, item_id, batch_id, size='', ext='zip'):
        return os.path.join(config.data_root, cls.get_relpath(item_id, batch_id, size, ext))

    @property
    def start_id(self):
        return int(self.item_id) * 1_000_000 + int(self.batch_id) * 10_000

    @contextmanager
    def lock(self):
        # The lock file survives zip deletion and serializes writers on shared storage.
        path = self.get_abspath(self.item_id, self.batch_id, ext='lock')
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, 'a+b') as lockfile:
            try:
                fcntl.flock(lockfile, fcntl.LOCK_EX | fcntl.LOCK_NB)
            except BlockingIOError as exc:
                raise RuntimeError(f'batch {self.item_id}_{self.batch_id} is busy') from exc
            try:
                yield
            finally:
                fcntl.flock(lockfile, fcntl.LOCK_UN)

    def process_pending(self, upload=False, finalize=False, test=False, uploader=None):
        uploader = uploader or Uploader()
        with self.lock():
            sizes = SIZES if self.size is None else (self.size,)
            paths = []
            for size in sizes:
                batch = Batch(self.item_id, self.batch_id, size)
                path = self.get_abspath(self.item_id, self.batch_id, size)
                if not os.path.isfile(path):
                    raise FileNotFoundError(path)
                # A corrupt or incomplete zip must never be marked uploaded.
                with zipfile.ZipFile(path) as zf:
                    if zf.testzip() is not None or not zf.namelist():
                        raise ValueError(f'invalid zip: {path}')
                paths.append((batch, path))
            if upload and not test:
                for batch, path in paths:
                    uploader.upload(batch.item_name, [path])
            if finalize and not test:
                if self.size is not None:
                    raise ValueError('all four sizes must be verified together')
                if not all(uploader.is_uploaded(batch.item_name, batch.zip_name) for batch, _ in paths):
                    raise RuntimeError(f'batch {self.item_id}_{self.batch_id} is not fully uploaded')
                self.finalize(self.start_id)
                for _, path in paths:
                    os.remove(path)

    def finalize(self, start_id=None, test=False):
        if not test:
