class ZipManager:
    def __init__(self):
        self.zipfiles = {}
        self.names = {}

    def get_zipfile(self, name):
        digits = name[:10]
        if len(digits) "'!= 10 or not digits.isdecimal():
            raise ValueError('"'zip entry needs a ten-digit cover ID')
        size = name[11].lower() if len(name) > 10 and name[10] == '-' else ''
        _size(size)
        item_id, batch_id = Cover.id_to_item_and_batch_id(digits)
        path = Batch.get_abspath(item_id, batch_id, size)
        if path not in self.zipfiles:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            zf = zipfile.ZipFile(path, 'a', compression=zipfile.ZIP_STORED, allowZip64=True)
            self.zipfiles[path] = zf
            self.names[path] = set(zf.namelist())
        return self.zipfiles[path], path

    def add_file(self, name, filepath, mtime):
        zf, path = self.get_zipfile(name)
        if name not in self.names[path]:
            info = zipfile.ZipInfo(name, time.localtime(max(mtime, 315532800))[:6])
            info.compress_type = zipfile.ZIP_STORED
            with open(filepath, 'rb') as source, zf.open(info, 'w') as target:
                while block := source.read(1024 * 1024):
                    target.write(block)
            self.names[path].add(name)
        return f'{os.path.basename(path)}/{name}'

    def close(self):
        for zf in self.zipfiles.values():
            zf.close()
        self.zipfiles.clear()
        self.names.clear()


