        return f'{protocol}://archive.org/download/{batch.item_name}/{batch.zip_name}/{filename}'

    def local_files(self):
        for size in SIZES:
            field = f'filename_{size}' if size else 'filename'
            filename = getattr(self, field, None)
            yield size, os.path.join(config.data_root, 'localdisk', filename) if filename else None

    def valid_files(self):
        return all(path and os.path.isfile(path) for _, path in self.local_files())


class Batch:
    def __init__(self, item_id, batch_id, size=None):
        self.item_id, self.batch_id = self._norm_ids(item_id, batch_id)
        self.size = None if size is None else _size(size)

    @staticmethod
    def _norm_ids(item_id, batch_id):
        item, batch = int(item_id), int(batch_id)
        if not (0 <= item <= 9999 and 0 <= batch <= 99):
            raise ValueError('item or batch ID out of range')
        return f'{item:04d}', f'{batch:02d}'

    @property
    def item_name(self):
        prefix = f'{self.size}_' if self.size else ''
        return f'{prefix}covers_{self.item_id}'

    @property
    def zip_name(self):
        return f'{self.item_name}_{self.batch_id}.zip'

    @classmethod
    def get_relpath(cls, item_id, batch_id, size='', ext='zip'):
        batch = cls(item_id, batch_id, size)
        return os.path.join('items', batch.item_name, f'{batch.item_name}_{batch.batch_id}.{ext.lstrip(\".\")}')

    @classmethod
    def get_abspath(cls, item_id, batch_id, size='', ext='zip'):
        return os.path.join(config.data_root, cls.get_relpath(item_id, batch_id, size, ext))

    @property
    def start_id(self):
        return int(self.item_id) * 1_000_000 + int(self.batch_id) * 10_000

    @contextmanager
    def lock(self):
        # The lock file survives zip deletion and serializes writers on shared storage.
        path = self.get_abspath(self.item_id, self.batch_id, ext='lock')
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, 'a+b') as lockfile:
            try:
                fcntl.flock(lockfile, fcntl.LOCK_EX | fcntl.LOCK_NB)
            except BlockingIOError as exc:
                raise RuntimeError(f'batch {self.item_id}_{self.batch_id} is busy') from exc
            try:
                yield
            finally:
                fcntl.flock(lockfile, fcntl.LOCK_UN)

    def process_pending(self, upload=False, finalize=False, test=False, uploader=None):
        uploader = uploader or Uploader()
        with self.lock():
            sizes = SIZES if self.size is None else (self.size,)
            paths = []
            for size in sizes:
                batch = Batch(self.item_id, self.batch_id, size)
                path = self.get_abspath(self.item_id, self.batch_id, size)
                if not os.path.isfile(path):
                    raise FileNotFoundError(path)
                # A corrupt or incomplete zip must never be marked uploaded.
                with zipfile.ZipFile(path) as zf:
                    if zf.testzip() is not None or not zf.namelist():
                        raise ValueError(f'invalid zip: {path}')
                paths.append((batch, path))
            if upload and not test:
                for batch, path in paths:
                    uploader.upload(batch.item_name, [path])
            if finalize and not test:
                if self.size is not None:
                    raise ValueError('all four sizes must be verified together')
                if not all(uploader.is_uploaded(batch.item_name, batch.zip_name) for batch, _ in paths):
                    raise RuntimeError(f'batch {self.item_id}_{self.batch_id} is not fully uploaded')
                self.finalize(self.start_id)
                for _, path in paths:
                    os.remove(path)

    def finalize(self, start_id=None, test=False):
        if not test:
            CoverDB.update_completed_batch(self.item_id, self.batch_id)


class ZipManager:
    def __init__(self):
        self.zipfiles = {}
        self.names = {}

    def get_zipfile(self, name):
        digits = name[:10]
        if len(digits) "'!= 10 or not digits.isdecimal():
            raise ValueError('"'zip entry needs a ten-digit cover ID')
        size = name[11].lower() if len(name) > 10 and name[10] == '-' else ''
        _size(size)
        item_id, batch_id = Cover.id_to_item_and_batch_id(digits)
        path = Batch.get_abspath(item_id, batch_id, size)
        if path not in self.zipfiles:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            zf = zipfile.ZipFile(path, 'a', compression=zipfile.ZIP_STORED, allowZip64=True)
            self.zipfiles[path] = zf
            self.names[path] = set(zf.namelist())
        return self.zipfiles[path], path

    def add_file(self, name, filepath, mtime):
        zf, path = self.get_zipfile(name)
        if name not in self.names[path]:
            info = zipfile.ZipInfo(name, time.localtime(max(mtime, 315532800))[:6])
            info.compress_type = zipfile.ZIP_STORED
            with open(filepath, 'rb') as source, zf.open(info, 'w') as target:
                while block := source.read(1024 * 1024):
                    target.write(block)
            self.names[path].add(name)
        return f'{os.path.basename(path)}/{name}'

    def close(self):
        for zf in self.zipfiles.values():
            zf.close()
        self.zipfiles.clear()
        self.names.clear()


def open_zipfile(name):
    manager = ZipManager()
    zf, _ = manager.get_zipfile(name)
    return zf


def get_zipfile(name):
    return open_zipfile(name)


def count_files_in_zip(filepath):
    with zipfile.ZipFile(filepath) as zf:
        return sum(name.lower().endswith('.jpg') for name in zf.namelist())


class Uploader:
    def upload(self, itemname, filepaths):
        return subprocess.run(['ia', 'upload', itemname, *filepaths, '--retries', '10'], check=True, capture_output=True, text=True)

    @staticmethod
    def is_uploaded(item, zip_filename, verbose=False):
        result = subprocess.run(['ia', 'list', item], check=True, capture_output=True, text=True)
        found = any(line.split()[0].lstrip('/') == zip_filename for line in result.stdout.splitlines() if line.split())
        if verbose:
            print(f'{item}/{zip_filename}: {\"uploaded\" if found else \"missing\"}')
        return found


